function collectAirtableRows({ previousState, records, offset }) {
  const state = previousState
    ? { records: [...previousState.records], cursors: [...previousState.cursors] }
    : { records: [], cursors: [] };
  if (previousState) {
    if (!Array.isArray(records)) throw new Error("Airtable returned no record array.");
    for (const record of records) {
      if (
        !record ||
        typeof record.id !== "string" ||
        !record.id ||
        !record.fields ||
        typeof record.fields !== "object" ||
        Array.isArray(record.fields)
      )
        throw new Error("Invalid Airtable record.");
      state.records.push(record);
    }
    if (offset !== undefined && offset !== null && (typeof offset !== "string" || !offset))
      throw new Error("Invalid Airtable cursor.");
    if (offset) {
      if (state.cursors.includes(offset))
        throw new Error("Airtable repeated its pagination cursor.");
      state.cursors.push(offset);
    }
  }
  const more = !previousState || !!offset;
  return {
    state,
    offset: more ? (offset ?? null) : null,
    more,
    hasRecords: state.records.length > 0,
  };
}

const state = collectAirtableRows({
  previousState: { records: [], cursors: [] },
  records: $input.all().map((i) => i.json),
  offset: null,
}).state;
return [{ json: { records: state.records } }];

function planSheetSync({ records, values, range, majorDimension }) {
  if (!Array.isArray(records) || !records.length)
    throw new Error("At least one selected Airtable record is required.");
  if (majorDimension !== "ROWS" || !Array.isArray(values) || !Array.isArray(values[0]))
    throw new Error("A sheet header row is required.");
  const headers = values[0];
  if (
    !headers.length ||
    headers.length > 5 ||
    headers.some((h) => typeof h !== "string" || !h) ||
    new Set(headers).size !== headers.length ||
    !headers.includes("Email")
  )
    throw new Error(
      "The A1:E1 headers must be unique text field names including Email, with no gaps.",
    );
  if (
    typeof range !== "string" ||
    range.lastIndexOf("!") < 1 ||
    range.slice(range.lastIndexOf("!") + 1) !== "A1:E1000"
  )
    throw new Error("The sheet response must identify the requested A1:E1000 lookup window.");
  const prefix = range.slice(0, range.lastIndexOf("!") + 1),
    keyIndex = headers.indexOf("Email"),
    existing = new Map(),
    sourceKeys = new Set(),
    data = [],
    newRows = [],
    matched = [],
    unchanged = [];
  if (values.length > 1000)
    throw new Error("The sheet response exceeds the configured lookup window.");
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!Array.isArray(row) || row.length > 5) throw new Error("Invalid sheet row.");
    const key = row[keyIndex];
    if (key !== null && key !== undefined && key !== "") {
      if (typeof key !== "string") throw new Error("Existing Email keys must be text.");
      if (existing.has(key))
        throw new Error("Duplicate Email keys exist in the target lookup window.");
      existing.set(key, i + 1);
    }
  }
  for (const record of records) {
    const fields = record?.fields,
      key = fields?.Email;
    if (
      !record?.id ||
      !fields ||
      typeof fields !== "object" ||
      Array.isArray(fields) ||
      typeof key !== "string" ||
      !key.trim()
    )
      throw new Error("Every selected record needs a nonempty text Email key.");
    if (sourceKeys.has(key)) throw new Error("Duplicate Email keys exist in the source batch.");
    sourceKeys.add(key);
    for (const h of headers) {
      const v = fields[h];
      if (v !== undefined && v !== null && !["string", "number", "boolean"].includes(typeof v))
        throw new Error("Mapped Airtable cells must be text,numbers,booleans or null.");
      if (typeof v === "number" && !Number.isFinite(v))
        throw new Error("Mapped numbers must be finite.");
    }
    const rowNumber = existing.get(key);
    if (rowNumber) {
      const before = data.length;
      headers.forEach((h, j) => {
        if (h !== "Email" && fields[h] !== undefined && fields[h] !== null)
          data.push({
            range: prefix + String.fromCharCode(65 + j) + rowNumber,
            majorDimension: "ROWS",
            values: [[fields[h]]],
          });
      });
      (data.length > before ? matched : unchanged).push({
        recordId: record.id,
        email: key,
        row: rowNumber,
      });
    } else
      newRows.push({
        recordId: record.id,
        email: key,
        values: headers.map((h) =>
          fields[h] === undefined || fields[h] === null ? "" : String(fields[h]),
        ),
      });
  }
  return {
    data: data.length
      ? data
      : [{ range: prefix + "A1", values: [["UNUSED"]], majorDimension: "ROWS" }],
    newRows,
    hasUpdates: data.length > 0,
    plan: {
      matched,
      unchanged,
      count: records.length,
      ranges: data.map((d) => d.range),
      cells: data.length,
      newRows,
      tableRange: range,
      width: headers.length,
    },
  };
}

return [
  {
    json: planSheetSync({
      records: $("Collect Selected Records").first().json.records,
      ...$input.first().json,
    }),
  },
];

return $("Match Email and Existing Headers")
  .first()
  .json.plan.newRows.map((json, index) => ({ json, pairedItem: { item: index } }));

function collectContactAppends({ plan, previousState, updatedRange, updatedRows, updatedCells }) {
  const state = previousState
    ? { index: previousState.index, inserted: [...previousState.inserted] }
    : { index: 0, inserted: [] };
  if (previousState) {
    const expected = plan.newRows[state.index],
      prefix = plan.tableRange.slice(0, plan.tableRange.lastIndexOf("!") + 1),
      suffix =
        typeof updatedRange === "string" && updatedRange.startsWith(prefix)
          ? updatedRange.slice(prefix.length)
          : "",
      match = suffix.match(/^A([0-9]+)(?::([A-E])([0-9]+))?$/);
    if (
      updatedRows !== 1 ||
      updatedCells !== plan.width ||
      !match ||
      match[1] !== (match[3] ?? match[1]) ||
      (match[2] ?? "A") !== String.fromCharCode(64 + plan.width)
    )
      throw new Error(
        "Append receipt does not confirm the new contact row. Inspect the sheet before retrying.",
      );
    state.inserted.push({
      recordId: expected.recordId,
      email: expected.email,
      range: updatedRange,
      row: Number(match[1]),
    });
    state.index++;
  }
  const next = plan.newRows[state.index];
  return { state, more: !!next, values: next ? [next.values] : [] };
}

const plan = $("Match Email and Existing Headers").first().json.plan,
  previousState =
    $runIndex === 0
      ? { index: 0, inserted: [] }
      : $("Confirm New Contact Append").all(0, $runIndex - 1)[0].json.state;
return [{ json: collectContactAppends({ plan, previousState, ...$input.first().json.updates }) }];

const plan = $("Match Email and Existing Headers").first().json.plan;
if ($input.all().length !== plan.newRows.length)
  throw Error("Append loop did not complete every new contact.");
return [{ json: { completedAppends: plan.newRows.length } }];

function confirmSheetSync({ plan, inserted, totalUpdatedRows, totalUpdatedCells, responses }) {
  if (inserted.length !== plan.newRows.length)
    throw new Error("All new contact appends must complete before updating existing rows.");
  if (plan.cells) {
    if (
      totalUpdatedRows !== plan.matched.length ||
      totalUpdatedCells !== plan.cells ||
      !Array.isArray(responses) ||
      responses.length !== plan.cells
    )
      throw new Error(
        "The update did not confirm every planned cell. Inspect the sheet before retrying.",
      );
    const canonical = (r) => String(r).replace(/([A-Z]+\d+):\1$/, "$1");
    for (let i = 0; i < responses.length; i++) {
      const r = responses[i];
      if (
        r.updatedRows !== 1 ||
        r.updatedCells !== 1 ||
        canonical(r.updatedRange) !== canonical(plan.ranges[i])
      )
        throw new Error("A cell write receipt is incomplete. Inspect the sheet before retrying.");
    }
  }
  return {
    rowsUpdated: plan.matched.length,
    rowsInserted: inserted.length,
    rowsUnchanged: plan.unchanged.length,
    totalRowsProcessed: plan.count,
    updated: plan.matched,
    inserted,
  };
}

const plan = $("Match Email and Existing Headers").first().json.plan,
  inserted = plan.newRows.length
    ? $("Confirm New Contact Append").all(0, plan.newRows.length - 1)[0].json.state.inserted
    : [];
return [{ json: confirmSheetSync({ plan, inserted, ...(plan.cells ? $input.first().json : {}) }) }];
